{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Elasticsearch encryption at rest is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The domain explicitly disables encryption at rest, leaving indexed log data stored on EBS volumes without storage-level encryption."
    },
    {
      "check_id": "CKV_AWS_247",
      "title": "Elasticsearch node-to-node encryption is not enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "Traffic exchanged between Elasticsearch nodes is not configured for encryption, which can expose sensitive log data while it moves within the cluster."
    },
    {
      "check_id": "CKV_AWS_83",
      "title": "HTTPS is not enforced for the Elasticsearch endpoint",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The domain does not enforce HTTPS or a minimum TLS version, allowing clients to potentially connect without adequate transport encryption."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Elasticsearch logging is not enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "No CloudWatch log publishing is configured, reducing visibility into Elasticsearch application errors and operational security events."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
  }

  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_application_logs.arn
    log_type                 = "ES_APPLICATION_LOGS"
    enabled                  = true
  }

  depends_on = [aws_cloudwatch_log_resource_policy.elasticsearch_logs]
}

resource "aws_cloudwatch_log_group" "elasticsearch_application_logs" {
  name              = "/aws/elasticsearch/enterprise-log-analytics-es/application-logs"
  retention_in_days = 365
}

resource "aws_cloudwatch_log_resource_policy" "elasticsearch_logs" {
  policy_name = "enterprise-log-analytics-es-logs"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "es.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.elasticsearch_application_logs.arn}:*"
      }
    ]
  })
}
",
  "fix_summary": "Enabled encryption at rest, node-to-node encryption, HTTPS enforcement, and TLS 1.2. Added retained CloudWatch application logging and the resource policy required for Elasticsearch to publish logs."
}
